def dijkstra_lazy(graph: Graph, start: str, target: str | None = None,
                  *, check: bool = True) -> Result:
    if check:
        validate_graph(graph, start, target)
    dist = dict.fromkeys(graph, inf)
    parent: dict[str, str] = {}
    finalized: set[str] = set()
    stats = Stats(pushes=1, peak_queue=1)
    ticket = count()
    dist[start] = 0
    queue = [(0, next(ticket), start)]
    while queue:
        popped_g, _, u = heappop(queue)
        stats.pops += 1
        if popped_g != dist[u]:
            stats.stale_pops += 1
            continue
        finalized.add(u)
        if u == target:
            return finish(dist, parent, start, target, stats, finalized)
        stats.expansions += 1
        for v, weight in graph[u]:
            stats.relaxations += 1
            candidate = popped_g + weight
            if candidate < dist[v]:
                dist[v] = candidate
                parent[v] = u
                heappush(queue, (candidate, next(ticket), v))
                stats.pushes += 1
                stats.improvements += 1
                stats.peak_queue = max(stats.peak_queue, len(queue))
    return finish(dist, parent, start, target, stats, finalized)

